## MCP - Speaker Identifier

**Endpoint:** POST /webhook/speaker-identifier

**InputSchema:**
```json
{
  "required": ["data", "assemblyai_api_key"],
  "properties": {
    "data": { "type": "string", "description": "Audio URL or base64 encoded audio" },
    "assemblyai_api_key": { "type": "string", "description": "AssemblyAI API key" },
    "source": { "type": "string", "description": "'url' or 'base64' (default: url)" },
    "options.speakers_expected": { "type": "number", "description": "Number of expected speakers" },
    "options.language": { "type": "string", "description": "Language code or 'auto'" },
    "options.include_transcription": { "type": "boolean", "description": "Include full transcript (default: true)" },
    "user_id": { "type": "string", "description": "User ID (optional, for tracing)" },
    "guild_id": { "type": "string", "description": "Guild ID (optional, for tracing)" },
    "user_request": { "type": "string", "description": "User request (optional, for tracing)" }
  }
}
```

**RFC-014 Context Support:**
```json
{
  "context": {
    "data": "https://...",
    "source": "url"
  },
  "plugin_context": {
    "api_keys": { "assemblyai": "..." }
  }
}
```

**Response:**
```json
{
  "success": true,
  "data": { "speakers": [...], "utterances": [...] },
  "meta": { "provider": "assemblyai" },
  "_trace": { ... }
}
```

**API:** AssemblyAI Speaker Diarization

parameters.jsCode:
// ============================================
// VALIDATION INPUT - RFC-014 Compatible
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- OPTIONAL context fields (for tracing only, NO validation errors) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- Extract audio data ---
const data = ctx.data || body.data;
const source = ctx.source || body.source || 'url';
const options = ctx.options || body.options || {};

// --- Extract API key ---
const assemblyaiKey = body.assemblyai_api_key 
  || ctx.assemblyai_api_key 
  || body.plugin_context?.api_keys?.assemblyai 
  || ctx.plugin_context?.api_keys?.assemblyai;

// --- Validation (REQUIRED fields only) ---
if (!data) errors.push('data (audio URL or base64) is required');
if (!assemblyaiKey) errors.push('assemblyai_api_key is required');

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

return {
  valid: true,
  data: data,
  source: source,
  options: options,
  assemblyai_api_key: assemblyaiKey,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR - with _trace
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

// For base64 input, we need to upload to a temporary storage
const prevData = $('Validate Input').first().json;
const base64Data = prevData.data;
const options = prevData.options || {};
const apiKey = prevData.assemblyai_api_key;

// Remove data URL prefix if present
const cleanBase64 = base64Data.replace(/^data:audio\/[a-z]+;base64,/, '');

return {
  json: {
    audioBase64: cleanBase64,
    options: options,
    needsUpload: true,
    assemblyai_api_key: apiKey,
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    user_request: prevData.user_request,
    startTime: prevData.startTime
  }
};

// Prepare URL audio input
const prevData = $('Validate Input').first().json;
const audioUrl = prevData.data;
const options = prevData.options || {};
const apiKey = prevData.assemblyai_api_key;

return {
  json: {
    audioUrl: audioUrl,
    options: options,
    needsUpload: false,
    assemblyai_api_key: apiKey,
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    user_request: prevData.user_request,
    startTime: prevData.startTime
  }
};

// Merge uploaded URL with options
const uploadResponse = $input.first().json;
const previousData = $('Prepare Base64').first().json;

return {
  json: {
    audioUrl: uploadResponse.upload_url,
    options: previousData.options,
    assemblyai_api_key: previousData.assemblyai_api_key,
    user_id: previousData.user_id,
    guild_id: previousData.guild_id,
    user_request: previousData.user_request,
    startTime: previousData.startTime
  }
};

// Prepare AssemblyAI transcription request
const input = $input.first().json;
const options = input.options || {};

const requestBody = {
  audio_url: input.audioUrl,
  speaker_labels: true
};

// Add optional parameters
if (options.speakers_expected) {
  requestBody.speakers_expected = options.speakers_expected;
}

if (options.language && options.language !== 'auto') {
  requestBody.language_code = options.language;
}

if (options.language === 'auto') {
  requestBody.language_detection = true;
}

return {
  json: {
    requestBody: requestBody,
    options: options,
    assemblyai_api_key: input.assemblyai_api_key,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request,
    startTime: input.startTime
  }
};

// Store transcript ID and options for polling
const response = $input.first().json;
const previousData = $('Prepare Transcription Request').first().json;

return {
  json: {
    transcriptId: response.id,
    status: response.status,
    options: previousData.options,
    pollCount: 0,
    startTime: previousData.startTime,
    assemblyai_api_key: previousData.assemblyai_api_key,
    user_id: previousData.user_id,
    guild_id: previousData.guild_id,
    user_request: previousData.user_request
  }
};

// ============================================
// BUILD TRANSCRIPTION ERROR - with _trace
// ============================================

const input = $input.first().json;
const storedData = $('Store Transcript ID').first().json;

return {
  success: false,
  error: {
    code: 'TRANSCRIPTION_ERROR',
    message: input.error || 'Transcription failed',
    http_status: 500
  },
  _trace: {
    service_response: { 
      transcription_error: input.error || 'Transcription failed',
      transcript_id: storedData.transcriptId
    },
    provider: 'assemblyai',
    mode: 'error',
    latency_ms: Date.now() - storedData.startTime,
    user_id: storedData.user_id,
    guild_id: storedData.guild_id,
    user_request: storedData.user_request
  },
  user_id: storedData.user_id,
  guild_id: storedData.guild_id,
  user_request: storedData.user_request
};

// Increment poll count and prepare for next poll
const response = $input.first().json;
const storedData = $('Store Transcript ID').first().json;

const pollCount = storedData.pollCount + 1;
const elapsedMs = Date.now() - storedData.startTime;

// Timeout after 30 minutes
if (elapsedMs > 30 * 60 * 1000) {
  throw new Error('Transcription timeout after 30 minutes');
}

return {
  json: {
    transcriptId: storedData.transcriptId,
    status: response.status,
    options: storedData.options,
    pollCount: pollCount,
    startTime: storedData.startTime,
    assemblyai_api_key: storedData.assemblyai_api_key,
    user_id: storedData.user_id,
    guild_id: storedData.guild_id,
    user_request: storedData.user_request
  }
};

// ============================================
// FORMAT SUCCESS RESPONSE - with _trace
// ============================================

const transcript = $input.first().json;
const storedData = $('Store Transcript ID').first().json;
const options = storedData.options || {};
const startTime = storedData.startTime;

// Group utterances by speaker
const speakerStats = {};
const utterances = transcript.utterances || [];

utterances.forEach(u => {
  if (!speakerStats[u.speaker]) {
    speakerStats[u.speaker] = {
      id: u.speaker,
      label: `Speaker ${u.speaker.replace('speaker_', '').toUpperCase()}`,
      total_speaking_time_ms: 0,
      utterance_count: 0
    };
  }
  speakerStats[u.speaker].total_speaking_time_ms += (u.end - u.start);
  speakerStats[u.speaker].utterance_count++;
});

// Calculate percentages
const totalSpeakingTime = Object.values(speakerStats).reduce((sum, s) => sum + s.total_speaking_time_ms, 0);
const speakers = Object.values(speakerStats).map(s => ({
  ...s,
  percentage: totalSpeakingTime > 0 ? Math.round((s.total_speaking_time_ms / totalSpeakingTime) * 100) : 0
}));

// Format utterances
const formattedUtterances = utterances.map(u => ({
  speaker: u.speaker,
  text: u.text,
  start_ms: u.start,
  end_ms: u.end,
  confidence: u.confidence
}));

// Build full transcript with speaker labels
const transcriptFull = utterances.map(u => {
  const label = speakerStats[u.speaker]?.label || u.speaker;
  return `${label}: ${u.text}`;
}).join('\n');

const latencyMs = Date.now() - startTime;

const response = {
  success: true,
  data: {
    speakers: speakers,
    utterances: options.include_transcription !== false ? formattedUtterances : undefined,
    transcript_full: options.include_transcription !== false ? transcriptFull : undefined,
    audio_duration_ms: transcript.audio_duration * 1000,
    num_speakers_detected: speakers.length,
    language_detected: transcript.language_code
  },
  meta: {
    provider: 'assemblyai',
    execution_mode: 'online',
    processing_time_ms: latencyMs,
    transcript_id: transcript.id
  },
  _trace: {
    service_response: {
      speakers_detected: speakers.length,
      audio_duration_ms: transcript.audio_duration * 1000,
      language_detected: transcript.language_code,
      transcript_id: transcript.id
    },
    provider: 'assemblyai',
    mode: 'speaker-identification',
    latency_ms: latencyMs,
    user_id: storedData.user_id,
    guild_id: storedData.guild_id,
    user_request: storedData.user_request
  },
  user_id: storedData.user_id,
  guild_id: storedData.guild_id,
  user_request: storedData.user_request
};

return { json: response };

